"use client";

import { useState, useEffect } from "react";
import Image from "next/image";

interface CarouselItem {
    id: number;
    title: string;
    description: string;
    category: string;
    image: string;
}

const carouselItems: CarouselItem[] = [
    {
        id: 1,
        category: "Branding Identity",
        title: "VIRTUAL IDENTITY",
        description: "We craft digital-first branding systems that resonate across all platforms. At 4WARD, we don't just design logos; we build living brand architectures that evolve with your vision, blending technical precision with artistic flair.",
        image: "/Portfolio.jpg", // Using existing as fallback
    },
    {
        id: 2,
        category: "Video Making",
        title: "MOTION NARRATIVES",
        description: "Cinematic storytelling meets cutting-edge motion graphics. Our video production team focuses on high-impact visual narratives that capture the essence of your project, ensuring every frame 'screams' quality and innovation.",
        image: "/Portfolio.jpg",
    },
    {
        id: 3,
        category: "3D Modeling",
        title: "SPATIAL DIMENSIONS",
        description: "Transforming abstract concepts into tangible 3D realities. We specialize in high-end 3D modeling and interactive spatial designs that push the boundaries of visual immersion, showcasing the '4WARD' thinking in every polygon.",
        image: "/Portfolio.jpg",
    },
    {
        id: 4,
        category: "Software Dev",
        title: "DIGITAL INFRA",
        description: "Building the backbone of modern digital experiences. Our development process bridges the gap between complex technical infrastructure and seamless user interaction, delivering robust, high-performance software solutions.",
        image: "/Portfolio.jpg",
    },
];

export default function AboutCarousel() {
    const [activeIndex, setActiveIndex] = useState(0);
    const [isTransitioning, setIsTransitioning] = useState(false);

    const nextSlide = () => {
        if (isTransitioning) return;
        setIsTransitioning(true);
        setActiveIndex((prev) => (prev + 1) % carouselItems.length);
        setTimeout(() => setIsTransitioning(false), 800);
    };

    const prevSlide = () => {
        if (isTransitioning) return;
        setIsTransitioning(true);
        setActiveIndex((prev) => (prev - 1 + carouselItems.length) % carouselItems.length);
        setTimeout(() => setIsTransitioning(false), 800);
    };

    const currentItem = carouselItems[activeIndex];

    return (
        <section className="relative w-full py-32 md:py-48 px-12 md:px-32 lg:px-48 overflow-hidden bg-white/20 backdrop-blur-sm mt-24">
            {/* Grid Pattern Background for this section */}
            <div className="absolute inset-0 grid-bg opacity-30 pointer-events-none" />

            <div className="relative z-10 grid grid-cols-1 lg:grid-cols-2 gap-24 items-center">
                {/* Left Column: Text Content */}
                <div className="max-w-2xl">
                    <div className="flex items-center gap-4 mb-8">
                        <span className="h-[2px] w-12 bg-[#d32f2f]" />
                        <span className="text-xs font-black uppercase tracking-[0.4em] text-[#d32f2f]">
                            {currentItem.category}
                        </span>
                    </div>

                    <div className="relative mb-8">
                        <h2 className="text-5xl md:text-6xl lg:text-7xl font-black tracking-tighter leading-[0.9] uppercase">
                            {currentItem.title.split(" ").map((word, i) => (
                                <span key={i} className="block last:text-outline">
                                    {word}
                                </span>
                            ))}
                        </h2>
                    </div>

                    <div className="relative py-8 border-y border-[#1a1a1a]/10">
                        <p className="text-sm md:text-base font-medium leading-relaxed text-[#1a1a1a]/80 max-w-md">
                            {currentItem.description}
                        </p>
                    </div>

                    <button className="mt-12 bg-[#1a1a1a] text-white px-10 py-5 font-black uppercase tracking-widest text-xs flex items-center gap-4 group transition-all hover:bg-[#d32f2f]">
                        Learn More
                        <svg
                            width="20" height="20" viewBox="0 0 24 24" fill="none"
                            className="transition-transform group-hover:translate-x-2"
                        >
                            <path d="M5 12H19M19 12L12 5M19 12L12 19" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />
                        </svg>
                    </button>
                </div>

                {/* Right Column: Visual Carousel */}
                <div className="relative h-[500px] flex items-center justify-center lg:justify-end">
                    <div className="relative w-full h-[400px] flex gap-6 items-center overflow-visible">
                        {carouselItems.map((item, index) => {
                            // Calculate relative position to active index
                            const diff = (index - activeIndex + carouselItems.length) % carouselItems.length;

                            const isActive = diff === 0;
                            const isNext = diff === 1;
                            const isPrev = diff === carouselItems.length - 1;
                            const isHidden = !isActive && !isNext && !isPrev;

                            return (
                                <div
                                    key={item.id}
                                    className={`absolute transition-all duration-700 ease-[cubic-bezier(0.23,1,0.32,1)] cursor-pointer ${isActive
                                        ? "z-30 w-full h-full opacity-100 scale-100 translate-x-0"
                                        : isNext
                                            ? "z-20 w-[80%] h-[80%] opacity-40 scale-90 translate-x-[40%] translate-y-[5%]"
                                            : isPrev
                                                ? "z-10 w-[60%] h-[60%] opacity-0 scale-75 -translate-x-[40%] translate-y-[10%]"
                                                : "z-0 opacity-0 scale-50 translate-x-[100%]"
                                        }`}
                                    onClick={() => {
                                        if (isNext) nextSlide();
                                        if (isPrev) prevSlide();
                                    }}
                                >
                                    <div className={`relative w-full h-full group overflow-hidden border border-[#e5e5e5] p-2 bg-white shadow-2xl ${isActive ? 'ring-4 ring-[#d32f2f]/10' : ''}`}>
                                        <div className="relative w-full h-full bg-[#f0f0f0] overflow-hidden">
                                            {/* Branded "4WARD" placeholder for 3D/Video items */}
                                            <div className="absolute inset-0 flex items-center justify-center bg-[#1a1a1a] text-white font-black overflow-hidden">
                                                <div className="text-[12rem] opacity-20 select-none tracking-tighter">4W</div>
                                                <div className="absolute inset-0 flex flex-col items-center justify-center p-8">
                                                    <span className="text-4xl tracking-tighter mb-2 italic scale-x-125">4WARD</span>
                                                    <span className="text-[8px] tracking-[0.5em] opacity-50 uppercase">{item.category}</span>

                                                    {/* Technical Decorations */}
                                                    <div className="absolute top-4 left-4 border border-white/20 p-1">
                                                        <div className="w-1 h-1 bg-[#d32f2f]" />
                                                    </div>
                                                    <div className="absolute bottom-4 right-4 border border-white/20 p-1">
                                                        <div className="w-1 h-1 bg-[#d32f2f]" />
                                                    </div>
                                                </div>

                                                {/* SVG Decorative overlay to give "3D/Technical" feel */}
                                                <svg className="absolute inset-0 w-full h-full opacity-30 pointer-events-none" viewBox="0 0 100 100" preserveAspectRatio="none">
                                                    <path d="M0 0L100 100M100 0L0 100" stroke="white" strokeWidth="0.1" />
                                                    <circle cx="50" cy="50" r="40" stroke="white" strokeWidth="0.1" fill="none" />
                                                    <rect x="10" y="10" width="80" height="80" stroke="white" strokeWidth="0.1" fill="none" />
                                                </svg>
                                            </div>
                                        </div>

                                        {/* Overlay info on active card */}
                                        {isActive && (
                                            <div className="absolute bottom-8 left-8 text-white z-40 animate-fade-in delay-300">
                                                <div className="text-[10px] font-bold uppercase tracking-[0.3em] mb-1 opacity-60">Project {item.id}</div>
                                                <div className="text-lg font-black tracking-widest">{item.category}</div>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            );
                        })}
                    </div>

                    {/* Controls */}
                    <div className="absolute bottom-0 right-0 flex gap-4 z-50 p-4">
                        <button
                            onClick={prevSlide}
                            className="w-16 h-16 border border-[#1a1a1a]/20 flex items-center justify-center bg-white hover:bg-[#1a1a1a] hover:text-white transition-all group shadow-lg"
                        >
                            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" className="transition-transform group-hover:-translate-x-1">
                                <path d="M19 12H5M5 12L12 19M5 12L12 5" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />
                            </svg>
                        </button>
                        <button
                            onClick={nextSlide}
                            className="w-16 h-16 border border-[#1a1a1a]/20 flex items-center justify-center bg-white hover:bg-[#d32f2f] hover:text-white transition-all group shadow-lg"
                        >
                            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" className="transition-transform group-hover:translate-x-1">
                                <path d="M5 12H19M19 12L12 5M19 12L12 19" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />
                            </svg>
                        </button>
                    </div>
                </div>
            </div>

            {/* Dynamic Background Indicator */}
            <div className="absolute top-1/2 left-4 -translate-y-1/2 flex flex-col gap-8">
                {carouselItems.map((_, i) => (
                    <div
                        key={i}
                        className={`w-[2px] h-8 transition-all duration-500 ${i === activeIndex ? "bg-[#d32f2f] h-16" : "bg-[#1a1a1a]/10"}`}
                    />
                ))}
            </div>
        </section>
    );
}

"use client";

import Image from "next/image";
import React, { useState, useEffect, useCallback } from "react";
import { motion, AnimatePresence, Variants } from "framer-motion";
import { projects } from "../lib/projects";
import Link from "next/link";
import { Suspense } from "react";
import { Canvas } from "@react-three/fiber";
import { OrbitControls, Stage, useGLTF, PerspectiveCamera } from "@react-three/drei";

export default function FeaturedProjects() {
    const [currentIndex, setCurrentIndex] = useState(0);
    const [direction, setDirection] = useState(0); // -1 for left, 1 for right
    const project = projects[currentIndex];

    const nextProject = useCallback(() => {
        setDirection(1);
        setCurrentIndex((prev) => (prev + 1) % projects.length);
    }, [projects.length]);

    const prevProject = () => {
        setDirection(-1);
        setCurrentIndex((prev) => (prev - 1 + projects.length) % projects.length);
    };

    // Auto-play timer logic
    useEffect(() => {
        const timer = setInterval(() => {
            nextProject();
        }, 15000); 

        return () => clearInterval(timer);
    }, [nextProject, currentIndex]);

    const variants: Variants = {
        enter: (direction: number) => ({
            x: direction > 0 ? 100 : -100,
            opacity: 0,
            scale: 0.98
        }),
        center: {
            x: 0,
            opacity: 1,
            scale: 1,
            transition: {
                x: { type: "spring", stiffness: 300, damping: 30 },
                opacity: { duration: 0.4 },
                scale: { duration: 0.4 }
            }
        },
        exit: (direction: number) => ({
            x: direction < 0 ? 100 : -100,
            opacity: 0,
            scale: 0.98,
            transition: {
                x: { type: "spring", stiffness: 300, damping: 30 },
                opacity: { duration: 0.3 }
            }
        })
    };

    return (
        <section className="relative w-full bg-[#f8f8f8] grid-bg font-jost overflow-hidden pt-12 pb-48 pr-12 pl-20 md:pr-24 md:pl-40">
            {/* ── Section Header ── */}
            <div className="relative z-50 mb-16 flex flex-col md:flex-row md:items-end md:justify-between gap-4">
                <div>
                    <motion.div 
                        initial={{ opacity: 0, x: -20 }}
                        whileInView={{ opacity: 1, x: 0 }}
                        viewport={{ once: true }}
                        className="flex items-center gap-3 mb-3"
                    >
                        <div className="w-12 h-[1px] bg-[#d32f2f]" />
                        <span className="text-xs font-black tracking-[0.4em] text-[#d32f2f] uppercase block">
                            Portfolio
                        </span>
                    </motion.div>
                    <motion.h2 
                        initial={{ opacity: 0, y: 30 }}
                        whileInView={{ opacity: 1, y: 0 }}
                        viewport={{ once: true }}
                        transition={{ delay: 0.1 }}
                        className="text-5xl md:text-6xl font-black uppercase leading-[0.85] tracking-tighter"
                    >
                        Selected <br />
                        <span className="text-outline" style={{ WebkitTextStroke: "1.2px #1a1a1a" }}>
                            Creations
                        </span>
                    </motion.h2>
                </div>

                {/* Carousel Controls */}
                <div className="flex items-center gap-6">
                    <button
                        onClick={prevProject}
                        className="group w-12 h-12 rounded-full border border-[#1a1a1a]/10 flex items-center justify-center hover:bg-[#d32f2f] hover:border-[#d32f2f] transition-all duration-500"
                    >
                        <svg className="group-hover:text-white transition-colors" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                            <line x1="19" y1="12" x2="5" y2="12" /><polyline points="12 19 5 12 12 5" />
                        </svg>
                    </button>
                    <div className="flex gap-3">
                        {projects.map((_, i) => (
                            <button
                                key={i}
                                onClick={() => {
                                    setDirection(i > currentIndex ? 1 : -1);
                                    setCurrentIndex(i);
                                }}
                                className={`h-1 transition-all duration-500 rounded-full ${i === currentIndex ? "w-8 bg-[#d32f2f]" : "w-1 bg-[#1a1a1a]/10 hover:bg-[#1a1a1a]/30"}`}
                            />
                        ))}
                    </div>
                    <button
                        onClick={nextProject}
                        className="group w-12 h-12 rounded-full border border-[#1a1a1a]/10 flex items-center justify-center hover:bg-[#d32f2f] hover:border-[#d32f2f] transition-all duration-500"
                    >
                        <svg className="group-hover:text-white transition-colors" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                            <line x1="5" y1="12" x2="19" y2="12" /><polyline points="12 5 19 12 12 19" />
                        </svg>
                    </button>
                </div>
            </div>

            {/* ── Main Showcase Container ── */}
            <div className="relative w-full min-h-[500px] flex items-center">
                <AnimatePresence initial={false} custom={direction} mode="wait">
                    <motion.div 
                        key={currentIndex}
                        custom={direction}
                        variants={variants}
                        initial="enter"
                        animate="center"
                        exit="exit"
                        className="w-full flex flex-col md:flex-row items-center gap-12 md:gap-0"
                    >
                        {/* Left Side: Overview & Numbering */}
                        <div className="relative z-20 w-full md:w-1/2 flex flex-col items-start pt-10">
                            <div className="relative">
                                <span className="text-[8rem] md:text-[10rem] font-black leading-none text-[#1a1a1a]/[0.05] select-none absolute -top-20 -left-6">
                                    {project.id}
                                </span>
                                <div className="relative mt-14">
                                    <h3 className="text-3xl md:text-4xl font-black uppercase tracking-tighter mb-6 leading-[0.9] max-w-sm">
                                        {project.name.substring(0, project.name.length / 2)}<span className="text-[#d32f2f]">{project.name.substring(project.name.length / 2)}</span>
                                    </h3>

                                    <div className="max-w-md bg-white/40 backdrop-blur-sm border border-[#1a1a1a]/5 p-7 shadow-[0_8px_30px_rgb(0,0,0,0.02)] relative overflow-hidden group">
                                        <div className="absolute top-0 left-0 w-1 h-full bg-[#d32f2f] opacity-20 group-hover:opacity-100 transition-opacity" />
                                        <p className="text-sm md:text-base leading-relaxed font-bold text-[#1a1a1a]/70 font-jost">
                                            {project.overview}
                                        </p>
                                    <Link href={`/projects/${project.slug}`}>
                                        <div className="mt-7 flex items-center gap-5 cursor-pointer group/link">
                                            <div className="w-10 h-10 rounded-full bg-[#1a1a1a] flex items-center justify-center text-white group-hover/link:bg-[#d32f2f] transition-all duration-500 overflow-hidden relative">
                                                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                                                    <line x1="7" y1="17" x2="17" y2="7" /><polyline points="7 7 17 7 17 17" />
                                                </svg>
                                            </div>
                                            <span className="text-[10px] font-black uppercase tracking-[0.2em] group-hover/link:translate-x-1.5 transition-transform duration-500">
                                                Case Study
                                            </span>
                                        </div>
                                    </Link>
                                    </div>
                                    
                                    <div className="mt-8 flex items-center gap-6 overflow-hidden">
                                        <span className="font-mono text-[9px] font-black text-[#1a1a1a]/30 uppercase tracking-[0.2em]">
                                            Yr / {project.year}
                                        </span>
                                        <div className="w-1 h-1 rounded-full bg-[#d32f2f]/30" />
                                        <span className="font-mono text-[9px] font-black text-[#d32f2f] uppercase tracking-[0.2em]">
                                            Cat / {project.category}
                                        </span>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Right Content Area: Device Mockups */}
                        <div className="relative w-full md:w-1/2 flex items-center justify-center pt-16 md:pt-0">
                            {/* Elegant background text overlaying the mockup transition area */}
                            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-full text-center opacity-[0.04] z-0 select-none pointer-events-none">
                                <h4 className="text-[14rem] md:text-[16rem] font-black uppercase tracking-tighter leading-none italic">
                                    {project.id}
                                </h4>
                            </div>

                            <div className="relative z-10 transform translate-x-0 md:translate-x-12 scale-90 md:scale-95 group">
                                <InteractiveTilt>
                                    {project.modelPath ? (
                                        <div className="relative w-full aspect-square min-h-[400px] flex items-center justify-center">
                                            <div className="w-full h-full relative">
                                                <Canvas shadows={{ type: 1 }} dpr={[1, 2]}>
                                                    <PerspectiveCamera makeDefault position={[0, 0, 7]} fov={35} />
                                                    <ambientLight intensity={0.8} />
                                                    <spotLight position={[10, 10, 10]} angle={0.15} penumbra={1} intensity={3} castShadow />
                                                    <pointLight position={[-10, 10, -10]} intensity={2} color={project.accentColor} />
                                                    <Suspense fallback={null}>
                                                        <Stage environment="city" intensity={1}>
                                                            <Model url={project.modelPath} />
                                                        </Stage>
                                                    </Suspense>
                                                    <OrbitControls autoRotate autoRotateSpeed={1.5} enableZoom={false} makeDefault />
                                                </Canvas>
                                            </div>
                                            
                                            {/* Premium Floating Detail for Model */}
                                            <div className="absolute -bottom-8 -right-8 w-24 md:w-32 z-50 transition-transform duration-700 group-hover:translate-x-4 group-hover:-translate-y-4">
                                                <div className="p-5 rounded-[1.2rem] shadow-2xl flex flex-col items-center justify-center transform -rotate-12 border-2 border-white/20 overflow-hidden group/detail" style={{ backgroundColor: project.accentColor }}>
                                                    <div className="absolute inset-0 bg-gradient-to-br from-white/30 to-transparent opacity-0 group-hover/detail:opacity-100 transition-opacity" />
                                                    <span className="text-white font-black text-3xl italic tracking-tigh relative z-10">{project.name.charAt(0)}</span>
                                                    <span className="text-white/40 text-[6px] font-black uppercase tracking-widest mt-0.5 relative z-10">Hardware</span>
                                                </div>
                                            </div>
                                        </div>
                                    ) : project.deviceType === "phone" ? (
                                        <div className="relative">
                                            <DeviceMockup scale={0.65}>
                                                <div className="relative w-full h-full bg-[#0a0a0a] overflow-hidden">
                                                    <Image 
                                                        src={project.image} 
                                                        alt={project.name} 
                                                        fill 
                                                        sizes="(max-width: 768px) 100vw, 30vw"
                                                        className="object-contain grayscale group-hover:grayscale-0 transition-all duration-700" 
                                                    />
                                                    {/* Sophisticated Glass Overlay */}
                                                    <div className="absolute inset-0 bg-gradient-to-t from-[#000]/90 via-transparent to-transparent p-7 flex flex-col justify-end">
                                                        <div className="w-12 h-1 mb-4 shadow-[0_0_15px_rgba(211,47,47,0.5)]" style={{ backgroundColor: project.accentColor }} />
                                                        <h5 className="text-white font-black uppercase text-lg mb-0.5 tracking-tighter leading-none">{project.mobileLabel}</h5>
                                                        <p className="text-white/40 text-[8px] font-black uppercase tracking-[0.3em]">{project.mobileSub}</p>
                                                    </div>
                                                    <div className="absolute inset-0 ring-1 ring-inset ring-white/10 pointer-events-none" />
                                                </div>
                                            </DeviceMockup>

                                            {/* Premium Floating Detail */}
                                            <div className="absolute -bottom-8 -right-8 w-24 md:w-32 z-50 transition-transform duration-700 group-hover:translate-x-4 group-hover:-translate-y-4">
                                                <div className="p-5 rounded-[1.2rem] shadow-2xl flex flex-col items-center justify-center transform -rotate-12 border-2 border-white/20 overflow-hidden group/detail" style={{ backgroundColor: project.accentColor }}>
                                                    <div className="absolute inset-0 bg-gradient-to-br from-white/30 to-transparent opacity-0 group-hover/detail:opacity-100 transition-opacity" />
                                                    <span className="text-white font-black text-3xl italic tracking-tigh relative z-10">{project.name.charAt(0)}</span>
                                                    <span className="text-white/40 text-[6px] font-black uppercase tracking-widest mt-0.5 relative z-10">Verify</span>
                                                </div>
                                            </div>
                                        </div>
                                    ) : (
                                        <div className="relative">
                                            <LaptopMockup scale={0.8}>
                                                <div className="relative w-full h-full bg-[#0a0a0a] overflow-hidden">
                                                    <Image 
                                                        src={project.image} 
                                                        alt={project.name} 
                                                        fill 
                                                        sizes="(max-width: 768px) 100vw, 50vw"
                                                        className="object-contain grayscale group-hover:grayscale-0 transition-all duration-700" 
                                                    />
                                                    {/* Sophisticated Glass Overlay */}
                                                    <div className="absolute inset-0 bg-gradient-to-t from-[#000]/90 via-transparent to-transparent p-9 flex flex-col justify-end">
                                                        <div className="w-12 h-1 mb-4 shadow-[0_0_15px_rgba(211,47,47,0.5)]" style={{ backgroundColor: project.accentColor }} />
                                                        <h5 className="text-white font-black uppercase text-xl mb-0.5 tracking-tighter leading-none">{project.mobileLabel}</h5>
                                                        <p className="text-white/40 text-[9px] font-black uppercase tracking-[0.3em]">{project.mobileSub}</p>
                                                    </div>
                                                    <div className="absolute inset-0 ring-1 ring-inset ring-white/10 pointer-events-none" />
                                                </div>
                                            </LaptopMockup>

                                            {/* Floating Tag Detail */}
                                            <div className="absolute -bottom-6 -right-5 w-28 md:w-36 z-50 transition-transform duration-700 group-hover:translate-x-4 group-hover:-translate-y-4">
                                                <div className="bg-[#1a1a1a] p-6 rounded-xl shadow-2xl border flex flex-col items-start gap-1.5 backdrop-blur-xl" style={{ borderColor: `${project.accentColor}40` }}>
                                                    <div className="flex gap-1">
                                                        {[1, 2, 3].map(i => <div key={i} className="w-1 h-1 rounded-full opacity-50" style={{ backgroundColor: project.accentColor }} />)}
                                                    </div>
                                                    <span className="text-white font-black text-xl italic tracking-tighter leading-none">PS_02</span>
                                                    <div className="w-full h-[1px] bg-white/5" />
                                                    <span className="text-[7px] font-black uppercase tracking-widest" style={{ color: project.accentColor }}>Active System</span>
                                                </div>
                                            </div>
                                        </div>
                                    )}
                                </InteractiveTilt>
                            </div>
                        </div>
                    </motion.div>
                </AnimatePresence>
            </div>
        </section>
    );
}

function InteractiveTilt({ children }: { children: React.ReactNode }) {
    const [rotateX, setRotateX] = useState(0);
    const [rotateY, setRotateY] = useState(0);

    const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
        const rect = e.currentTarget.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        const centerX = rect.width / 2;
        const centerY = rect.height / 2;
        const degX = (y - centerY) / 20;
        const degY = (centerX - x) / 20;
        
        setRotateX(degX);
        setRotateY(degY);
    };

    const handleMouseLeave = () => {
        setRotateX(0);
        setRotateY(0);
    };

    return (
        <motion.div
            onMouseMove={handleMouseMove}
            onMouseLeave={handleMouseLeave}
            animate={{ rotateX, rotateY }}
            transition={{ type: "spring", stiffness: 150, damping: 20 }}
            style={{ transformStyle: "preserve-3d" }}
        >
            {children}
        </motion.div>
    );
}

function DeviceMockup({ children, scale = 1 }: { children: React.ReactNode, scale?: number }) {
    return (
        <div className="relative" style={{ perspective: "2000px" }}>
            <div className="relative mx-auto" style={{ width: `${300 * scale}px`, height: `${620 * scale}px`, transformStyle: "preserve-3d" }}>
                <div className="absolute inset-0 bg-black rounded-[2.8rem] border-[10px] border-[#1a1a1a] shadow-inner overflow-hidden">
                    <div className="w-full h-full relative bg-zinc-900 overflow-hidden">{children}</div>
                    <div className="absolute top-4 left-1/2 -translate-x-1/2 w-24 h-7 bg-black rounded-full z-50" />
                </div>
                <div className="absolute inset-0 rounded-[2.8rem] pointer-events-none z-40 bg-gradient-to-br from-white/5 to-transparent" />
            </div>
        </div>
    );
}

function LaptopMockup({ children, scale = 1 }: { children: React.ReactNode, scale?: number }) {
    const w = 500 * scale;
    const h = 320 * scale;
    return (
        <div className="relative" style={{ perspective: "2000px" }}>
            <div className="relative mx-auto flex flex-col items-center" style={{ width: `${w}px`, transformStyle: "preserve-3d" }}>
                {/* Screen */}
                <div
                    className="relative bg-[#0a0a0a] rounded-t-xl border-[12px] border-[#1a1a1a] overflow-hidden shadow-2xl"
                    style={{ width: `${w}px`, height: `${h}px` }}
                >
                    <div className="w-full h-full bg-zinc-900">{children}</div>
                    <div className="absolute top-0 left-1/2 -translate-x-1/2 w-2 h-2 rounded-full bg-[#1a1a1a] mt-1" />
                </div>
                {/* Base / Keyboard Area */}
                <div
                    className="relative bg-[#1a1a1a] rounded-b-xl shadow-xl"
                    style={{
                        width: `${w + 40}px`,
                        height: "15px",
                        background: "linear-gradient(to bottom, #1a1a1a, #0a0a0a)"
                    }}
                />
                <div
                    className="relative bg-[#0a0a0a] rounded-b-2xl mx-auto"
                    style={{ width: `${w + 20}px`, height: "8px" }}
                />
            </div>
        </div>
    );
}

function Model({ url }: { url: string }) {
    const { scene } = useGLTF(url, "https://www.gstatic.com/draco/versioned/decoders/1.5.5/");
    // Clone the scene so it can be used in multiple canvases safely
    const clonedScene = React.useMemo(() => scene.clone(), [scene]);
    // Ensure the model faces forward initially by rotating it 180 degrees if it's starting from the back
    return <primitive object={clonedScene} rotation={[0, Math.PI, 0]} />;
}

